sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	// Add your code here

	// Identify the parent record 
	var parentSysId = current.weekly_action || previous.weekly_action;
	if (!parentSysId) {
		return;
	}

	var totalHours = 0; 
	var completedHours = 0;

	// Query all children for this parent 
	var childGR = new GlideRecord('x_942105_12_week_y_daily_tactic'); 
	childGR.addQuery('weekly_action', parentSysId); 
	childGR.query(); 

	while (childGR.next()) { 
		var hours = parseFloat(childGR.time_estimate || 0);
		totalHours += hours; 

		// Add to completed hours only if marked complete 
		if (childGR.completed == true || childGR.u_complete == 'true') { 
			completedHours += hours; 
		}
	}

	// Calculate percent complete 
	var percentComplete = 0; 
	if (totalHours > 0) { 
		percentComplete = (completedHours / totalHours) * 100; 
		} 

	// Round to 2 decimal places 
	percentComplete = parseFloat(percentComplete.toFixed(2));

	// Update the parent record 
	var parentGR = new GlideRecord('x_942105_12_week_y_weekly_action'); 
	if (parentGR.get(parentSysId)) { 

		parentGR.time_estimate = totalHours; 
		parentGR.u_percent_complete = percentComplete;

		// Optional: auto-mark parent complete when 100% 
		if (percentComplete == 100) { 
			parentGR.completed = true; 
			} else { 
				parentGR.completed = false; }

		var updateResult = parentGR.update(); 
	}

})(current, previous);
